const email=sessionStorage.getItem('uniify-pending-email'),status=document.querySelector('#flow-status'),button=document.querySelector('#resend-link');
document.querySelector('#verification-recipient').textContent=email?'Open the confirmation link sent to '+email+' to continue. Check your spam folder if it has not arrived.':'Create an account to receive your confirmation link.';
button.disabled=!email;
button.onclick=async()=>{button.disabled=true;try{const response=await fetch('/api/auth/resend-link',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({email})});const result=await response.json();if(!response.ok)throw Error(result.error||'Unable to resend the confirmation link.');status.textContent='A new confirmation link has been requested. Check your inbox. You can resend again in 60 seconds.';setTimeout(()=>button.disabled=false,60000)}catch(error){status.textContent=error.message;button.disabled=false}};
